// Registers the service worker generated by vite-plugin-pwa (sw.js). Updates
// are silent: the new worker activates on this launch and the next launch runs
// the new build (plan section 9, FR-003). In dev there is no sw.js, so skip.
export const registerServiceWorker = (): void => {
    if (import.meta.env.DEV || !('serviceWorker' in navigator)) {
        return;
    }
    window.addEventListener('load', () => {
        // A failed registration must never break the game; it only means
        // "online only" until the next launch.
        navigator.serviceWorker.register('/sw.js', { scope: '/' }).catch(() => undefined);
    });
};
